                  if sum(x != background for x in grid[r]) >= 2)
    sequence = [grid[bottom][c] for c in range(W) if grid[bottom][c] != background]
    interior = Counter(grid[r][c] for r in range(bottom) for c in range(W)
                       if grid[r][c] != background).most_common(1)[0][0]

    # Locate each tile by its one non-interior marker, then recover its rectangle.
    tiles = []
    for r in range(bottom):
        for c in range(W):
            if grid[r][c] == background or grid[r][c] == interior:
                continue
            top, bot, left, right = r, r, c, c
            while top > 0 and grid[top-1][c] == interior:
                top -= 1
            while bot+1 < bottom and grid[bot+1][c] == interior:
                bot += 1
            while left > 0 and grid[r][left-1] == interior:
                left -= 1
            while right+1 < W and grid[r][right+1] == interior:
                right += 1
            if not any(t[:4] == [top,bot,left,right] for t in tiles):
                tiles.append([top,bot,left,right,grid[r][c]])
    tiles.sort(key=lambda t: (t[0], t[2]))

    # Consecutive sequence entries refer to successive tiles, in reading order.
    for i in range(min(len(tiles), len(sequence)-1)):
