def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bottom = max(r for r in range(h) if sum(v != bg for v in grid[r]) >= 2)
    seq = [grid[bottom][c] for c in range(w) if grid[bottom][c] != bg]
    fill = Counter(grid[r][c] for r in range(bottom) for c in range(w)
                   if grid[r][c] != bg).most_common(1)[0][0]
    tiles = []
    for r in range(bottom):
        for c in range(w):
            color = grid[r][c]
            if color in (bg, fill):
                continue
            top, bot, left, right = r, r, c, c
            while top and grid[top-1][c] == fill:
                top -= 1
            while bot+1 < bottom and grid[bot+1][c] == fill:
                bot += 1
            while left and grid[r][left-1] == fill:
                left -= 1
            while right+1 < w and grid[r][right+1] == fill:
                right += 1
            box = (top,bot,left,right,color)
            if box not in tiles:
                tiles.append(box)
    tiles.sort(key=lambda t:(t[0],t[2]))
    for i in range(min(len(seq)-1,len(tiles))):
        r0,r1,c0,c1,color = tiles[i]
        candidates = []
