            t0,t1,d0,d1,_ = t
            if max(c0,d0) <= min(c1,d1):
                candidates.append((abs(r0-t0),True,t))
            elif max(r0,t0) <= min(r1,t1):
                candidates.append((abs(c0-d0),False,t))
        if not candidates:
            continue
        _,vertical,(t0,t1,d0,d1,_) = min(candidates,key=lambda x:x[0])
        if vertical:
            # A connector is centered in the tile, not as wide as its frame.
            c = (max(c0,d0)+min(c1,d1))//2
            rows = range(r1+1,t0) if r1 < t0 else range(r0-1,t1,-1)
            for r in rows:
